from pathlib import Path
from html import escape
import json
root=Path(__file__).resolve().parents[1]
m=json.loads((root/'assets/materials/manifest.json').read_text(encoding='utf-8'))
brands=[('MIDORI','回转印、日期章、可上色线稿章','https://www.midori-store.net/SHOP/183572/list.html','自制日期文字章、单色印泥；未内置品牌印面'),('KODOMO NO KAO','手账功能章、小图标章、组合使用','https://www.kodomonokao.com/','原创日常文字章；未内置品牌角色及原版图案'),('Shachihata','印台配色、组合数字与日历章','https://www.shachihata.jp/products/list.php?category_id=11480','自选墨色、浓淡与缺墨；未复制其色号或整套章面'),('BGM','碎片贴、透明贴、便签贴等','https://www.bgmlife.jp/products/','纸质白边、半透明叠贴；立体及金属触感未模拟'),('Mind Wave','动物、生活场景、主题贴纸','https://www.mindwave-store.com/c/all/seal','原创小物与动物；未内置其角色或原版图案'),('bande','逐枚剥取的卷装贴纸','https://bande.ne.jp/?mode=f3','独立透明底素材可复制叠贴；未复刻品牌花型')]
brands += [('KING JIM / KITTA','预切胶带、透明贴与纸质贴纸','https://www.kingjim.co.jp/hitotoki/sp/kitta/lineup.html','局部裁切、半透明叠贴与打印排布；未内置原版花型或烫金'),('古川纸工','和纸碎片贴纸','https://www.furukawashiko-online.shop/c/furukawa-product/item-fp/flakesticker-fp','独立贴纸、柔和透底与白边；未模拟真实和纸纤维'),('mt / KAMOI','和纸胶带与原创胶带','https://shop.masking-tape.jp/','单图可排连续花边与边框；未复制品牌联名图案')]
rows=''.join(f'<tr><td><a href="{url}" target="_blank" rel="noopener">{escape(name)}</a></td><td>{escape(types)}</td><td>{escape(status)}</td></tr>' for name,types,url,status in brands)
cards=''.join(f'<article><img loading="lazy" src="../assets/materials/{escape(i["thumb"])}" alt="{escape(i["name"])}"><p>{escape(i["name"])}</p></article>' for i in m['items'] if i.get('pack') in ('craft-original','motif-original'))
html=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>印章与贴纸 · 手账工坊</title><style>figure{{margin:0;min-width:0}}body{{margin:0;background:#f6f2eb;color:#4b5048;font:15px/1.8 system-ui,sans-serif}}main{{max-width:1180px;margin:auto;padding:28px 18px}}a{{color:#58775c}}h1,h2{{font-weight:500}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}}article{{background:#fff;border:1px solid #ded8cb;border-radius:12px;padding:12px;text-align:center}}article img{{width:100%;height:130px;object-fit:contain}}article p{{font-size:13px}}.scroll{{overflow:auto}}table{{border-collapse:collapse;width:100%;min-width:580px}}th,td{{border:1px solid #d6d0c4;padding:12px;text-align:left}}.note{{background:#eee8dd;border-radius:12px;padding:14px}}@media print{{article{{break-inside:avoid}}}}</style><main><p>手账工坊 · 2026-11-12</p><h1>印章与贴纸小工坊</h1><p><a href="../?tab=editor">打开小工坊</a> · <a href="../?tab=library">打开素材库</a> · <a href="CRAFT-2026-11-12.md">使用说明与验证</a></p><p>新增48种图案的彩色贴纸与线稿印章，共96件；另有此前72件日常印章和贴纸。共{len(m['items'])}件内置素材；在素材库主题里选「日常文字印章」或「生活小物贴纸」。在编辑器可自制文字日期章，支持局部裁切、可调白边阴影、连续花边、四周边框、花环与实际尺寸贴纸排布；也可把已有图片处理成印泥、纸质白边、半透明叠贴与和纸感效果。</p><div class="note">这里没有收齐所有品牌的所有商品。下表是已核对的{len(brands)}个品牌官方参考入口，状态逐项写明。原创图案与品牌原版分开：本轮未下载或分发品牌商品图。真实烫金、压纹、绒面和材质触感不能靠普通打印还原。</div><h2>裁切、花边与打印示例</h2><p><a href="CRAFT-LAYOUT-2026-11-12.md">查看本轮用法与验证</a>。同一张图案可做连续花边、四周边框和花环，再按实际尺寸打印。</p><div class="grid"><figure><img style="width:100%;height:190px;object-fit:contain;background:#fffdf7" src="screenshots/pattern-strip.png" alt="连续花边"><figcaption>连续花边</figcaption></figure><figure><img style="width:100%;height:190px;object-fit:contain;background:#fffdf7" src="screenshots/pattern-frame.png" alt="四周边框"><figcaption>四周边框</figcaption></figure><figure><img style="width:100%;height:190px;object-fit:contain;background:#fffdf7" src="screenshots/pattern-wreath.png" alt="图案花环"><figcaption>图案花环</figcaption></figure><figure><img style="width:100%;height:190px;object-fit:contain;background:#fffdf7" src="screenshots/sticker-sheet.png" alt="贴纸打印页"><figcaption>实际尺寸贴纸页</figcaption></figure></div><p><a href="craft-coverage.html">查看品牌分类逐项覆盖清单</a></p><h2>品牌与效果覆盖</h2><div class="scroll"><table><thead><tr><th>品牌与官方入口</th><th>参考方向</th><th>工坊当前覆盖</th></tr></thead><tbody>{rows}</tbody></table></div><h2>168件印章与贴纸预览</h2><section class="grid">{cards}</section><p>素材均由工坊独立绘制，标注CC0。品牌参考只用于了解产品类型，不代表获得其图案授权或与品牌存在合作。</p></main></html>'''
(root/'docs/craft-guide.html').write_text(html,encoding='utf-8')
print(json.dumps({'previews':168,'brand_references':len(brands),'materials':len(m['items'])}))
